import java.util.*;
public class AStar {
    static int heuristic(int[] a, int[] b) {
        return Math.abs(a[0]-b[0]) + Math.abs(a[1]-b[1]); // Manhattan
    }
    public List<int[]> astar(int[][] grid, int[] start, int[] goal) {
        int n = grid.length, m = grid[0].length;
        int[][] gScore = new int[n][m];
        for (int[] r : gScore) Arrays.fill(r, Integer.MAX_VALUE);
        gScore[start[0]][start[1]] = 0;
        PriorityQueue<int[]> open = new PriorityQueue<>(Comparator.comparingInt(a->a[0]));
        open.offer(new int[]{heuristic(start,goal), start[0], start[1]});
        Map<String,int[]> came = new HashMap<>();
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        while (!open.isEmpty()) {
            int[] cur = open.poll();
            int r=cur[1], c=cur[2];
            if (r==goal[0] && c==goal[1]) return reconstructPath(came, goal);
            for (int[] d : dirs) {
                int nr=r+d[0], nc=c+d[1];
                if (nr<0||nr>=n||nc<0||nc>=m||grid[nr][nc]==1) continue;
                int ng = gScore[r][c] + 1;
                if (ng < gScore[nr][nc]) {
                    gScore[nr][nc] = ng;
                    came.put(nr+","+nc, new int[]{r,c});
                    open.offer(new int[]{ng+heuristic(new int[]{nr,nc},goal),nr,nc});
                }
            }
        }
        return Collections.emptyList();
    }
    List<int[]> reconstructPath(Map<String,int[]> came, int[] goal) {
        List<int[]> path = new ArrayList<>();
        int[] cur = goal;
        while (cur != null) { path.add(0, cur); cur = came.get(cur[0]+","+cur[1]); }
        return path;
    }
}

