#include <bits/stdc++.h>
using namespace std;
typedef pair<int,pair<int,int>> pii3;
int heuristic(int r1,int c1,int r2,int c2){ return abs(r1-r2)+abs(c1-c2); }
vector<pair<int,int>> astar(vector<vector<int>>& g, pair<int,int> s, pair<int,int> goal) {
    int n=g.size(), m=g[0].size();
    vector<vector<int>> gs(n, vector<int>(m, INT_MAX));
    map<pair<int,int>,pair<int,int>> came;
    gs[s.first][s.second]=0;
    priority_queue<pii3,vector<pii3>,greater<pii3>> pq;
    pq.push({heuristic(s.first,s.second,goal.first,goal.second),s});
    int dr[]={0,0,1,-1}, dc[]={1,-1,0,0};
    while(!pq.empty()){
        auto [f,cur]=pq.top(); pq.pop();
        if(cur==goal){ vector<pair<int,int>> path; while(came.count(cur)){path.push_back(cur);cur=came[cur];} reverse(path.begin(),path.end()); return path; }
        for(int d=0;d<4;d++){
            int nr=cur.first+dr[d], nc=cur.second+dc[d];
            if(nr<0||nr>=n||nc<0||nc>=m||g[nr][nc]) continue;
            int ng=gs[cur.first][cur.second]+1;
            if(ng<gs[nr][nc]){ gs[nr][nc]=ng; came[{nr,nc}]=cur; pq.push({ng+heuristic(nr,nc,goal.first,goal.second),{nr,nc}}); }
        }
    }
    return {};
}
